function pixelPanel(context,x,y,w,h,cut=8,fill='#fff9e8',stroke='#1a3557',shadow=true){context.save();context.lineJoin='miter';const path=()=>{context.beginPath();context.moveTo(x+cut,y);context.lineTo(x+w-cut,y);context.lineTo(x+w,y+cut);context.lineTo(x+w,y+h-cut);context.lineTo(x+w-cut,y+h);context.lineTo(x+cut,y+h);context.lineTo(x,y+h-cut);context.lineTo(x,y+cut);context.closePath();};if(shadow){context.translate(6,6);path();context.fillStyle='#14294455';context.fill();context.translate(-6,-6);}path();context.fillStyle=fill;context.fill();context.strokeStyle=stroke;context.lineWidth=4;context.stroke();context.restore();}
function bubble(p){if(!p.message)return;ctx.save();ctx.font='700 18px ui-monospace, "Noto Sans TC", monospace';const lines=[];let line='';for(const ch of p.message){if(ch==='\n'){lines.push(line);line='';continue;}if(ctx.measureText(line+ch).width>220&&line){lines.push(line);line=ch;}else line+=ch;}lines.push(line);const lineHeight=27,w=Math.max(94,...lines.map(text=>ctx.measureText(text).width+36)),h=lines.length*lineHeight+28,x=Math.max(10,Math.min(W-w-10,Math.round(p.x-w/2))),y=Math.max(10,Math.round(p.y-178-h));pixelPanel(ctx,x,y,w,h,10);const tipX=Math.max(x+22,Math.min(x+w-22,p.x));ctx.fillStyle='#fff9e8';ctx.strokeStyle='#1a3557';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(tipX-10,y+h-2);ctx.lineTo(tipX,y+h+13);ctx.lineTo(tipX+10,y+h-2);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#183352';ctx.textAlign='center';ctx.textBaseline='middle';const centerY=y+h/2-1;lines.forEach((text,index)=>ctx.fillText(text,x+w/2,centerY+(index-(lines.length-1)/2)*lineHeight));ctx.restore();}
