function drawDeskBack(s){withStationStyle(s,()=>{const x=s.x,y=s.y;if(s.type===1){drawMonitor(x-47,y-116,82,56);drawMonitor(x+47,y-112,82,56);}else drawMonitor(x,y-116,s.type===2?112:104,61);if(s.type===2){ctx.fillStyle='#d8e1e5';ctx.fillRect(x-104,y-86,37,49);ctx.fillStyle='#253a51';ctx.fillRect(x-96,y-47,6,6);}ctx.fillStyle='#eef3f4';ctx.fillRect(x-48,y-43,78,12);for(let key=0;key<8;key++)ctx.fillRect(x-43+key*9,y-40,5,4);ctx.fillStyle='#d5dee3';ctx.fillRect(x+70,y-45,19,25);});}
function drawDeskFront(s){withStationStyle(s,()=>{const x=s.x,y=s.y;ctx.fillStyle='#0b3765';ctx.beginPath();ctx.moveTo(x-126,y-48);ctx.lineTo(x+126,y-48);ctx.lineTo(x+113,y+7);ctx.lineTo(x-113,y+7);ctx.closePath();ctx.fill();ctx.fillStyle='#1762a0';ctx.beginPath();ctx.moveTo(x-118,y-42);ctx.lineTo(x+118,y-42);ctx.lineTo(x+108,y-1);ctx.lineTo(x-108,y-1);ctx.closePath();ctx.fill();ctx.fillStyle='#082947';ctx.fillRect(x-113,y+7,226,18);ctx.fillRect(x-103,y+25,18,76);ctx.fillRect(x+85,y+25,18,76);ctx.fillStyle='#133c60';ctx.fillRect(x-98,y+25,13,65);ctx.fillRect(x+85,y+25,13,65);if(s.name){pixelPanel(ctx,x-45,y+35,90,27,5,'#fff4cf','#172e49',false);ctx.fillStyle='#173552';ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='800 14px ui-monospace, monospace';ctx.fillText(s.name,x,y+49);}});}
function drawPerson(i,time,walk){const p=people[i];if(p.status!=='present')return;const t=time/1000;let bob=walk&&selected===i?Math.sin(t*17)*3:0,tilt=0;if(p.mood==='happy')bob-=Math.abs(Math.sin(t*4))*12;if(p.mood==='angry')bob+=Math.sin(t*24)*2;if(p.mood==='joy'){tilt=Math.sin(t*7)*.1;bob-=Math.abs(Math.sin(t*7))*8;}if(p.mood==='sad')tilt=Math.sin(t*2)*.035;ctx.save();ctx.translate(p.x,p.y);if(i===selected){ctx.strokeStyle='#e9b94e';ctx.fillStyle='#ffdd7828';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,-2,45,12,0,0,Math.PI*2);ctx.fill();ctx.stroke();}ctx.rotate(tilt);sprite(ctx,i,p.dir,0,bob);ctx.restore();hits.push({type:'person',i,x:p.x-53,y:p.y-150,w:106,h:150});}
function drawPhotoCard(i){const p=people[i];if(!p.photo)return;let image=photoImages.get(i);if(!image){image=new Image();image.src=p.photo;photoImages.set(i,image);}const side=p.x>W-155?-1:1,x=Math.round(side>0?p.x+64:p.x-140),y=Math.round(p.y-151),w=76,h=65;ctx.save();ctx.fillStyle='#132a45';ctx.fillRect(x+6,y+6,w,h);ctx.fillStyle='#fff8dc';ctx.fillRect(x,y,w,h);ctx.fillStyle='#1b3f68';ctx.fillRect(x,y,w,4);ctx.fillRect(x,y+h-4,w,4);ctx.fillRect(x,y,4,h);ctx.fillRect(x+w-4,y,4,h);ctx.fillStyle='#e4b94f';ctx.fillRect(x+4,y+4,10,5);ctx.fillRect(x+w-14,y+4,10,5);if(image.complete&&image.naturalWidth)ctx.drawImage(image,x+8,y+10,w-16,h-23);ctx.fillStyle='#1d3a5b';ctx.font='800 8px ui-monospace, monospace';ctx.textAlign='center';ctx.fillText('PHOTO',x+w/2,y+h-6);ctx.restore();hits.push({type:'photo',i,x,y,w,h});}
function drawOverlay(i){const p=people[i];if(p.status!=='present')return;bubble(p);drawPhotoCard(i);const mood=moods.find(item=>item.id===p.mood);if(mood){const side=p.photo?-1:(p.x>W-120?-1:1),x=p.x+side*78,y=p.y-126;ctx.save();pixelPanel(ctx,x-27,y-27,54,54,7,'#fff7d7','#1c3b61',true);drawPixelSymbol(ctx,mood.symbol,x,y,5);ctx.restore();}}
function drawStatusMarker(s){const p=stationPerson(s);if(!p||p.status==='present')return;const status=statuses.find(item=>item.id===p.status),x=s.x,y=s.y-151;pixelPanel(ctx,x-42,y-43,84,76,9,'#edf2f3','#293d52',true);drawPixelSymbol(ctx,status.symbol,x,y-8,5);ctx.fillStyle='#273b50';ctx.font='800 13px ui-monospace, "Noto Sans TC", monospace';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(status.label,x,y+25);hits.push({type:'status',i:names.indexOf(p.name),x:x-45,y:y-46,w:90,h:82});}
function render(time){const dt=Math.min((time-last)/1000||0,.04);last=time;const walk=moving(dt);ctx.clearRect(0,0,W,H);drawOffice();if(ready){hits=[];const layers=[];stations.forEach(s=>{layers.push({depth:s.y-80,draw:()=>drawChair(s)});layers.push({depth:s.y-45,draw:()=>drawDeskBack(s)});layers.push({depth:s.y+106,draw:()=>drawDeskFront(s)});});people.forEach((p,i)=>layers.push({depth:p.y,draw:()=>drawPerson(i,time,walk)}));layers.sort((a,b)=>a.depth-b.depth).forEach(layer=>layer.draw());people.forEach((p,i)=>drawOverlay(i));stations.forEach(drawStatusMarker);}requestAnimationFrame(render);}
load(sheet).then(()=>{ready=true;$('loading').hidden=true;select(0);document.querySelectorAll('.roster-button canvas').forEach((canvas,i)=>portrait(canvas.getContext('2d'),i));}).catch(()=>{$('loading').textContent='場景圖片載入失敗，請重新整理頁面。';});select(0);syncLevels();requestAnimationFrame(render);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'set_character_status',description:'選取設計師並設定心情、出勤狀態與頭頂對話。照片與對話僅儲存於本機瀏覽器。',inputSchema:{type:'object',properties:{name:{type:'string',enum:names},message:{type:'string',maxLength:60},mood:{type:'string',enum:['','happy','angry','sad','joy']},status:{type:'string',enum:['present','offwork','toilet','abroad','out']}},required:['name'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!names.includes(input.name)||input.message!==undefined&&(typeof input.message!=='string'||input.message.length>60)||input.mood!==undefined&&!['','happy','angry','sad','joy'].includes(input.mood)||input.status!==undefined&&!statuses.some(status=>status.id===input.status))throw Error('人物、對話、心情或狀態無效');const i=names.indexOf(input.name);if(input.message!==undefined)people[i].message=input.message;if(input.mood!==undefined)people[i].mood=input.mood;if(input.status!==undefined)people[i].status=input.status;select(i);save();return {name:people[i].name,message:people[i].message,mood:people[i].mood,status:people[i].status};}});}catch{}}
